function toPaddedHex(value, width) {
  return value.toString(16).padStart(width, '0');
}

export function formatPythonString(value) {
  let output = "'";

  for (const char of value) {
    const codePoint = char.codePointAt(0);

    if (char === '\\') {
      output += '\\\\';
    } else if (char === '\'') {
      output += '\\\'';
    } else if (char === '\n') {
      output += '\\n';
    } else if (char === '\r') {
      output += '\\r';
    } else if (char === '\t') {
      output += '\\t';
    } else if (codePoint >= 0x20 && codePoint <= 0x7e) {
      output += char;
    } else if (codePoint <= 0xff) {
      output += `\\x${toPaddedHex(codePoint, 2)}`;
    } else if (codePoint <= 0xffff) {
      output += `\\u${toPaddedHex(codePoint, 4)}`;
    } else {
      output += `\\U${toPaddedHex(codePoint, 8)}`;
    }
  }

  output += "'";
  return output;
}

export function formatPythonValue(value) {
  if (typeof value === 'string') {
    return formatPythonString(value);
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : 'nan';
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
  }

  return formatPythonDict(value);
}

export function formatPythonDict(value) {
  const entries = Object.entries(value).map(
    ([key, entryValue]) => `${formatPythonString(key)}: ${formatPythonValue(entryValue)}`,
  );
  return `{${entries.join(', ')}}`;
}

