import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;
const INNER_PAD = 0x36;
const OUTER_PAD = 0x5c;

function normalizeKey(keyBytes) {
  if (keyBytes.length <= BLOCK_SIZE) {
    return keyBytes;
  }

  return sha256(keyBytes);
}

export function hmacSha256(keyBytes, messageBytes) {
  const normalizedKey = normalizeKey(keyBytes);
  const block = new Uint8Array(BLOCK_SIZE);
  block.set(normalizedKey);

  const innerInput = new Uint8Array(BLOCK_SIZE + messageBytes.length);
  const outerInput = new Uint8Array(BLOCK_SIZE + 32);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerInput[index] = block[index] ^ INNER_PAD;
    outerInput[index] = block[index] ^ OUTER_PAD;
  }

  innerInput.set(messageBytes, BLOCK_SIZE);
  const innerHash = sha256(innerInput);
  outerInput.set(innerHash, BLOCK_SIZE);

  return sha256(outerInput);
}

