import { decodeBase64UrlToJson, encodeBase64UrlFromBytes, encodeJsonToBase64Url } from './base64url.mjs';
import { hmacSha256 } from './hmac_sha256.mjs';
import { encodeUtf8 } from './utf8.mjs';

function signSegments(headerSegment, payloadSegment, secret) {
  const signingInput = `${headerSegment}.${payloadSegment}`;
  const signature = hmacSha256(encodeUtf8(secret), encodeUtf8(signingInput));
  return encodeBase64UrlFromBytes(signature);
}

export function encodeToken(payload, secret) {
  const headerSegment = encodeJsonToBase64Url({
    alg: 'HS256',
    typ: 'JWT',
  });
  const payloadSegment = encodeJsonToBase64Url(payload);
  const signatureSegment = signSegments(headerSegment, payloadSegment, secret);
  return `${headerSegment}.${payloadSegment}.${signatureSegment}`;
}

export function decodeToken(token, secret, options = {}, algorithms = ['HS256']) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Not enough segments');
  }

  const [headerSegment, payloadSegment, signatureSegment] = parts;
  const header = decodeBase64UrlToJson(headerSegment);

  if (!Array.isArray(algorithms) || !algorithms.includes(header.alg)) {
    throw new Error('The specified alg value is not allowed');
  }

  const expectedSignature = signSegments(headerSegment, payloadSegment, secret);
  if (signatureSegment !== expectedSignature) {
    throw new Error('Signature verification failed.');
  }

  const payload = decodeBase64UrlToJson(payloadSegment);
  if (options.verify_iat && payload.iat !== undefined && !Number.isInteger(payload.iat)) {
    throw new Error('Issued At claim (iat) must be an integer.');
  }

  return payload;
}

